function timezoneClockText(timezone, offset, includeReferenceTimes = true) {
  const now = Date.now();
  const format = value => new Date(value).toISOString().replace("T", " ").replace(/\.\d{3}Z$/, "");
  const sign = offset >= 0 ? "+" : "";
  const local = `\`${format(now + offset * 60 * 60 * 1000)} ${timezone}\``;
  if (!includeReferenceTimes) return `\`${timezone}\` (UTC${sign}${offset}, GMT${sign}${offset})\n**Local:** ${local}`;
  return `\`${timezone}\` (UTC${sign}${offset}, GMT${sign}${offset})\n` +
    `**UTC:** \`${format(now)} UTC\`\n` +
    `**GMT:** \`${format(now)} GMT\`\n` +
    `**Local:** ${local}`;
}
function timezoneLocalTimeText(timezone, offset) {
  const now = Date.now();
  const format = value => new Date(value).toISOString().replace("T", " ").replace(/\.\d{3}Z$/, "");
  return `\`${format(now + offset * 60 * 60 * 1000)} ${timezone}\``;
}
globalThis.timezoneClockText = timezoneClockText;

function buildPersonalTimezoneContainer(userId, username = "User", guildId = null) {
  const timezone = db.users?.[userId]?.timezone || "UTC";
  const offset = TIMEZONE_OFFSETS_HOURS[timezone] ?? 0;
  const dropdownZones = [
    "UTC", "GMT", "Africa/Cairo", "Africa/Johannesburg", "America/New_York",
    "America/Chicago", "America/Denver", "America/Los_Angeles", "America/Sao_Paulo",
    "Asia/Dubai", "Asia/Kolkata", "Asia/Dhaka", "Asia/Bangkok", "Asia/Shanghai",
    "Asia/Tokyo", "Asia/Seoul", "Australia/Sydney", "Pacific/Auckland",
    "Europe/London", "Europe/Paris", "Europe/Berlin", "Europe/Moscow",
    "CET", "EET", "IST"
  ].filter(value => value in TIMEZONE_OFFSETS_HOURS);
  const options = dropdownZones.map(value => {
    const hours = TIMEZONE_OFFSETS_HOURS[value];
    return {
    label: value,
    description: `UTC${hours >= 0 ? "+" : ""}${hours}`,
    value
    };
  });
  const select = new StringSelectMenuBuilder()
    .setCustomId(`personal_timezone_select_${userId}`)
    .setPlaceholder("Select your timezone")
    .addOptions(options);
  return new ContainerBuilder()
    .addTextDisplayComponents(t => t.setContent(
      `### Personal Timezone\n` +
      `**User:** ${username}\n` +
      `**Current timezone:** ${timezoneClockText(timezone, offset)}\n\n` +
      `Choose a timezone below, or use \`${getPrefix(guildId)}stz <TZ>\` directly.`
    ))
    .addSeparatorComponents(s => s.setSpacing(SeparatorSpacingSize.Small).setDivider(true))
    .addActionRowComponents(new ActionRowBuilder().addComponents(select))
    .addSeparatorComponents(s => s.setSpacing(SeparatorSpacingSize.Small))
    .addTextDisplayComponents(t => t.setContent("-# Only you can use this selector."));
}
globalThis.buildPersonalTimezoneContainer = buildPersonalTimezoneContainer;

/* ================= MESSAGE CREATE EVENT ================= */

/* ===============================================================
   UNIVERSAL RESOLVERS
   resolveUser   – @mention | snowflake ID | username/displayName
   resolveMember – same but returns GuildMember
   resolveChannel– #mention | snowflake ID | channel name
   resolveRole   – @mention | snowflake ID | role name
   =============================================================== */

async function resolveUser(msg, argVal) {
  if (argVal) return await resolveUserCached(client, msg.guild, argVal);
  return msg.mentions.users.first() || null;
}

async function resolveMember(msg, argVal) {
  const mentioned = msg.mentions.members.first();
  if (mentioned) return mentioned;
  if (!argVal) return null;
  return await resolveMemberCached(msg.guild, argVal);
}

async function resolveChannel(msg, argVal) {
  const mentioned = msg.mentions.channels.first();
  if (mentioned) return mentioned;
  if (!argVal) return null;
  const input = String(argVal).replace(/[<#>]/g, "").trim();
  if (!input) return null;
  return await resolveChannelCached(client, msg.guild, input);
}

async function resolveRole(msg, argVal) {
  const mentioned = msg.mentions.roles.first();
  if (mentioned) return mentioned;
  if (!argVal) return null;
  const input = String(argVal).replace(/^<@&(\d{17,20})>$/, "$1").replace(/[<@&>]/g, "").trim();
  if (!input) return null;
  if (/^\d{17,20}$/.test(input)) {
    return msg.guild.roles.cache.get(input) || await msg.guild.roles.fetch(input).catch(() => null);
  }
  const query = input.replace(/^@+/, "").trim().toLowerCase();
  return msg.guild.roles.cache.find(r =>
    r.name.toLowerCase() === query ||
    r.name.toLowerCase().startsWith(query)
  ) || null;
}


/* ───────────────────────────────────────────────────────────────
   sendPurgeLog — central purge-log dispatcher (Premium).
   Logs any bot-deleted messages (manual purge OR automod) to the
   guild's configured purge-log channel.

   @param guild          Guild
   @param deletedMsgs    Message | Message[]
   @param reason         String label, e.g. "Manual Purge", "Bad Word", "Spam"
   @param moderator      User/Member who triggered the action (null = Automod)
   @param sourceChannel  Channel where messages were deleted
─────────────────────────────────────────────────────────────────*/

/* ─────────────────────────────────────────────────────────────────────
   sendVerifyPanel(guild, channel, v)
   Posts (or re-posts) the static verify panel into `channel`.
   Deletes any previous panel message first (uses v.panelMessageId).
   Returns the new Message, or null on failure.
────────────────────────────────────────────────────────────────────── */
async function sendVerifyPanel(guild, channel, v) {
  // Delete the old panel if we tracked its ID
  if (v.panelMessageId) {
    const oldChannel = v.panelChannelId
      ? (guild.channels.cache.get(v.panelChannelId) || await guild.channels.fetch(v.panelChannelId).catch(() => null))
      : channel;
    const old = oldChannel?.isTextBased?.() ? await oldChannel.messages.fetch(v.panelMessageId).catch(() => null) : null;
    if (old) await old.delete().catch(() => {});
    v.panelMessageId = null;
    v.panelChannelId = null;
  }

  const title   = v.title   || "Verification Required";
  const desc    = v.message || "Click the button below to gain access to the server!";
  const ARR     = getEmoji("arrow");

  const ageNote = v.ageGateEnabled
    ? `\n-# ⏳ Accounts newer than **${v.ageGateDays ?? 30} days** require approval; older accounts auto-verify.`
    : "";

  const btn = new ButtonBuilder()
    .setCustomId(`verify_btn_${guild.id}`)
    .setLabel("Verify Me")
    .setEmoji(getEmojiObject("tick"))
    .setStyle(ButtonStyle.Success);

  const container = new ContainerBuilder()
    .setAccentColor(getThemeColor(guild.id))
    .addTextDisplayComponents(t => t.setContent(
      `## ${EMOJIS.thinking} ${title}\n` +
      `> ${desc.replace(/{user}/g, "new members")}` +
      ageNote
    ))
    .addSeparatorComponents(s => s.setSpacing(SeparatorSpacingSize.Small).setDivider(true))
    .addActionRowComponents(new ActionRowBuilder().addComponents(btn))
    .addSeparatorComponents(s => s.setSpacing(SeparatorSpacingSize.Small))
    .addTextDisplayComponents(t => t.setContent(`-# ${guild.name}`));

  const sent = await channel.send({ components: [container], flags: MessageFlags.IsComponentsV2 }).catch(() => null);
  if (sent) {
    v.panelMessageId = sent.id;
    v.panelChannelId = channel.id;
    saveDB();
  }
  return sent;
}

/* ─────────────────────────────────────────────────────────────────────
   buildVerifyConfigContainer(guild, guildId, v)
   Renders the interactive verify config panel shown by !verify config.
────────────────────────────────────────────────────────────────────── */
function ensureVerifyData(guildId) {
  const gd = guildData(guildId);
  gd.verify ||= {};
  const v = gd.verify;
  const arrayKeys = ["extraRoles", "whitelistUsers", "whitelistRoles", "approverUsers", "approverRoles", "createdRoleIds", "createdChannelIds"];
  for (const key of arrayKeys) {
    if (!Array.isArray(v[key])) v[key] = [];
    v[key] = [...new Set(v[key].map(id => String(id || "").trim()).filter(Boolean))];
  }
  if (!v.pendingApprovals || typeof v.pendingApprovals !== "object") v.pendingApprovals = {};
  if (v.category === undefined) v.category = null;
  if (v.panelMessageId === undefined) v.panelMessageId = null;
  if (v.panelChannelId === undefined) v.panelChannelId = null;
  if (v.ageGateDays === undefined) v.ageGateDays = 30;
  if (v.ageGateEnabled === undefined) v.ageGateEnabled = false;
  if (v.ageGateConfigured === undefined) v.ageGateConfigured = false;
  if (!v.title) v.title = "Verification Required";
  if (!v.message) v.message = "Click the button below to verify!";
  return v;
}

function verifyAgeGateRuleText(days) {
  const safeDays = Math.max(1, parseInt(days, 10) || 30);
  return `Accounts newer than **${safeDays} days** need approval before joining.\nAccounts older than **${safeDays} days** auto-verify after clicking the button.`;
}

function verifyAgeGateStatusText(v = {}) {
  const days = Math.max(1, parseInt(v.ageGateDays, 10) || 30);
  return v.ageGateEnabled
    ? `<:tick:1559236522711187577> Enabled - newer than **${days} days** needs approval; older auto-verifies`
    : `<:scross:1559257945030525110> Disabled - all users auto-verify after clicking`;
}

function setVerifyAgeGate(guildId, input) {
  const v = ensureVerifyData(guildId);
  const raw = String(input || "").trim().toLowerCase();
  if (!raw) {
    return {
      ok: false,
      title: "Age Gate",
      message:
        `**Current:** ${verifyAgeGateStatusText(v)}\n\n` +
        "`verify agegate on` - Enable\n" +
        "`verify agegate off` - Disable\n" +
        "`verify agegate <days>` - Set threshold and auto-enable",
    };
  }
  if (["on", "enable", "enabled", "true"].includes(raw)) {
    v.ageGateEnabled = true;
    v.ageGateConfigured = true;
    if (!parseInt(v.ageGateDays, 10) || parseInt(v.ageGateDays, 10) < 1) v.ageGateDays = 30;
    saveDB();
    return { ok: true, title: "Age Gate Enabled", message: verifyAgeGateRuleText(v.ageGateDays) };
  }
  if (["off", "disable", "disabled", "false"].includes(raw)) {
    v.ageGateEnabled = false;
    v.ageGateConfigured = true;
    saveDB();
    return { ok: true, title: "Age Gate Disabled", message: "All accounts will verify directly after clicking the Verify button." };
  }
  const days = parseInt(raw, 10);
  if (!Number.isNaN(days) && days > 0) {
    v.ageGateDays = days;
    v.ageGateEnabled = true;
    v.ageGateConfigured = true;
    saveDB();
    return { ok: true, title: "Age Gate Updated", message: `${verifyAgeGateRuleText(days)}\n\`Age gate auto-enabled.\`` };
  }
  return { ok: false, title: "Invalid Input", message: "Enter a number of days like `7`, or `on`/`off`." };
}

function verifyMemberHasConfiguredAccess(member, userIds = [], roleIds = []) {
  if (!member) return false;
  if (userIds.includes(member.id)) return true;
  return member.roles?.cache?.some?.(role => roleIds.includes(role.id)) || false;
}

function isVerifyWhitelisted(member, guildId = member?.guild?.id) {
  if (!member || !guildId) return false;
  const v = ensureVerifyData(guildId);
  return member.id === member.guild?.ownerId ||
    member.permissions?.has?.(PermissionsBitField.Flags.Administrator) ||
    verifyMemberHasConfiguredAccess(member, v.whitelistUsers, v.whitelistRoles);
}

function canApproveVerification(member, guildId = member?.guild?.id, userId = member?.id) {
  if (!member || !guildId) return false;
  const v = ensureVerifyData(guildId);
  return userId === member.guild?.ownerId ||
    member.permissions?.has?.(PermissionsBitField.Flags.Administrator) ||
    member.permissions?.has?.(PermissionsBitField.Flags.ManageGuild) ||
    verifyMemberHasConfiguredAccess(member, v.approverUsers, v.approverRoles);
}

function canManageVerification(member, guild = member?.guild, userId = member?.id) {
  return canManageAntiNuke(guild, userId);
}

async function ensureVerifyRoles(guild, v = ensureVerifyData(guild.id)) {
  const created = [];
  let verifiedRole = v.role ? guild.roles.cache.get(v.role) : null;
  if (!verifiedRole) {
    verifiedRole = await guild.roles.create({ name: "Verified", color: 0x808080, reason: "Verification system setup" });
    v.role = verifiedRole.id;
    v.createdRoleIds.push(verifiedRole.id);
    created.push(`Verified role: ${verifiedRole}`);
  }
  if (verifiedRole.managed || !verifiedRole.editable) {
    throw new Error(`The Verified role (${verifiedRole.name}) must be below the bot's highest role.`);
  }
  if (verifiedRole.permissions.has(PermissionsBitField.Flags.Administrator) || verifiedRole.permissions.has(PermissionsBitField.Flags.ManageGuild)) {
    throw new Error(`The Verified role (${verifiedRole.name}) cannot have Administrator or Manage Server.`);
  }
  let unverifiedRole = v.unverifiedRole ? guild.roles.cache.get(v.unverifiedRole) : null;
  if (!unverifiedRole) {
    unverifiedRole = await guild.roles.create({ name: "Unverified", color: 0x808080, reason: "Verification system setup" });
    v.unverifiedRole = unverifiedRole.id;
    v.createdRoleIds.push(unverifiedRole.id);
    created.push(`Unverified role: ${unverifiedRole}`);
  }
  if (unverifiedRole.managed || !unverifiedRole.editable) {
    throw new Error(`The Unverified role (${unverifiedRole.name}) must be below the bot's highest role.`);
  }
  v.createdRoleIds = [...new Set(v.createdRoleIds)];
  return { verifiedRole, unverifiedRole, created };
}

async function ensureVerifyChannels(guild, v, roles) {
  const created = [];
  const botMember = guild.members.me || await guild.members.fetchMe();
  let category = v.category ? guild.channels.cache.get(v.category) : null;
  if (!category || category.type !== ChannelType.GuildCategory) {
    category = await guild.channels.create({
      name: "Verification",
      type: ChannelType.GuildCategory,
      permissionOverwrites: [
        { id: guild.roles.everyone.id, deny: [PermissionsBitField.Flags.ViewChannel] },
        { id: botMember.id, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.ManageChannels] },
      ],
      reason: "Verification system setup",
    });
    v.category = category.id;
    v.createdChannelIds.push(category.id);
    created.push(`Category: ${category}`);
  }

  let verifyChannel = v.channel ? guild.channels.cache.get(v.channel) : null;
  if (!verifyChannel?.isTextBased?.()) {
    verifyChannel = await guild.channels.create({
      name: "verify-here",
      type: ChannelType.GuildText,
      parent: category.id,
      topic: "Verify here to gain access to the server.",
      permissionOverwrites: [
        { id: guild.roles.everyone.id, deny: [PermissionsBitField.Flags.ViewChannel] },
        { id: roles.unverifiedRole.id, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.ReadMessageHistory], deny: [PermissionsBitField.Flags.SendMessages, PermissionsBitField.Flags.AddReactions] },
        { id: roles.verifiedRole.id, deny: [PermissionsBitField.Flags.ViewChannel] },
        { id: botMember.id, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages, PermissionsBitField.Flags.EmbedLinks] },
      ],
      reason: "Verification system setup",
    });
    v.channel = verifyChannel.id;
    v.createdChannelIds.push(verifyChannel.id);
    created.push(`Verify channel: ${verifyChannel}`);
  } else if (verifyChannel.parentId !== category.id) {
    await verifyChannel.setParent(category.id, { lockPermissions: false, reason: "Verification system setup" }).catch(() => {});
  }

  let approvalChannel = v.approvalChannel ? guild.channels.cache.get(v.approvalChannel) : null;
  if (!approvalChannel?.isTextBased?.()) {
    approvalChannel = await guild.channels.create({
      name: "alt-approve",
      type: ChannelType.GuildText,
      parent: category.id,
      topic: "Manual verification requests for approved staff.",
      permissionOverwrites: [
        { id: guild.roles.everyone.id, deny: [PermissionsBitField.Flags.ViewChannel] },
        { id: roles.unverifiedRole.id, deny: [PermissionsBitField.Flags.ViewChannel] },
        { id: botMember.id, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages, PermissionsBitField.Flags.EmbedLinks] },
      ],
      reason: "Verification system setup",
    });
    v.approvalChannel = approvalChannel.id;
    v.createdChannelIds.push(approvalChannel.id);
    created.push(`Approval channel: ${approvalChannel}`);
  } else if (approvalChannel.parentId !== category.id) {
    await approvalChannel.setParent(category.id, { lockPermissions: false, reason: "Verification system setup" }).catch(() => {});
  }

  let logsChannel = v.logs ? guild.channels.cache.get(v.logs) : null;
  if (!logsChannel?.isTextBased?.()) {
    logsChannel = await guild.channels.create({
      name: "verify-logs",
      type: ChannelType.GuildText,
      parent: category.id,
      topic: "Verification system activity logs.",
      permissionOverwrites: [
        { id: guild.roles.everyone.id, deny: [PermissionsBitField.Flags.ViewChannel] },
        { id: roles.unverifiedRole.id, deny: [PermissionsBitField.Flags.ViewChannel] },
        { id: botMember.id, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages, PermissionsBitField.Flags.EmbedLinks] },
      ],
      reason: "Verification system setup",
    });
    v.logs = logsChannel.id;
    v.createdChannelIds.push(logsChannel.id);
    created.push(`Log channel: ${logsChannel}`);
  } else if (logsChannel.parentId !== category.id) {
    await logsChannel.setParent(category.id, { lockPermissions: false, reason: "Verification system setup" }).catch(() => {});
  }
  await logsChannel.permissionOverwrites.edit(guild.roles.everyone, { ViewChannel: false }, { reason: "Verification log privacy" });
  await logsChannel.permissionOverwrites.edit(roles.unverifiedRole, { ViewChannel: false }, { reason: "Verification log privacy" });
  await logsChannel.permissionOverwrites.edit(botMember, { ViewChannel: true, SendMessages: true, ReadMessageHistory: true, EmbedLinks: true }, { reason: "Verification log access" });
  for (const role of guild.roles.cache.values()) {
    if (role.id !== guild.roles.everyone.id && role.permissions.has(PermissionsBitField.Flags.ManageGuild)) {
      await logsChannel.permissionOverwrites.edit(role, { ViewChannel: true, SendMessages: true, ReadMessageHistory: true }, { reason: "Verification manager log access" }).catch(() => {});
    }
  }
  v.createdChannelIds = [...new Set(v.createdChannelIds)];
  return { category, verifyChannel, approvalChannel, logsChannel, created };
}

async function setVerifyCategory(guild, category, v = ensureVerifyData(guild.id)) {
  if (!category || category.type !== ChannelType.GuildCategory) {
    throw new Error("Select a valid category channel.");
  }
  const previousCategoryId = v.category;
  v.category = category.id;
  const roles = await ensureVerifyRoles(guild, v);
  const channels = await ensureVerifyChannels(guild, v, roles);
  for (const channelId of [v.channel, v.approvalChannel]) {
    const channel = channelId ? (guild.channels.cache.get(channelId) || await guild.channels.fetch(channelId).catch(() => null)) : null;
    if (channel && channel.parentId !== category.id) {
      await channel.setParent(category.id, { lockPermissions: false, reason: "Verification category changed" });
    }
  }
  await syncVerifyPermissions(guild, v);
  const panel = await sendVerifyPanel(guild, channels.verifyChannel, v);
  if (!panel) throw new Error("Could not send the Verify button container in the verify channel.");
  if (previousCategoryId && previousCategoryId !== category.id && v.createdChannelIds.includes(previousCategoryId)) {
    const previousCategory = guild.channels.cache.get(previousCategoryId) || await guild.channels.fetch(previousCategoryId).catch(() => null);
    if (previousCategory?.type === ChannelType.GuildCategory && previousCategory.children.cache.size === 0) {
      await previousCategory.delete("Replaced verification category").catch(() => {});
      v.createdChannelIds = v.createdChannelIds.filter(id => id !== previousCategoryId);
    }
  }
  saveDB();
  return category;
}

async function setVerifyChannel(guild, channel, v = ensureVerifyData(guild.id)) {
  if (!channel?.isTextBased?.() || channel.isThread?.()) {
    throw new Error("Select a server text channel for verification.");
  }
  v.channel = channel.id;
  const roles = await ensureVerifyRoles(guild, v);
  await ensureVerifyChannels(guild, v, roles);
  await syncVerifyPermissions(guild, v);
  const panel = await sendVerifyPanel(guild, channel, v);
  if (!panel) {
    throw new Error("Could not send the Verify button container. Check View Channel and Send Messages permissions.");
  }
  saveDB();
  return { channel, panel };
}

async function setVerifyApprovalChannel(guild, channel, v = ensureVerifyData(guild.id)) {
  if (!channel?.isTextBased?.() || channel.isThread?.()) {
    throw new Error("Select a server text channel for verification approvals.");
  }
  v.approvalChannel = channel.id;
  const roles = await ensureVerifyRoles(guild, v);
  const channels = await ensureVerifyChannels(guild, v, roles);
  await syncVerifyPermissions(guild, v);
  if (!v.panelMessageId || v.panelChannelId !== channels.verifyChannel.id) {
    const panel = await sendVerifyPanel(guild, channels.verifyChannel, v);
    if (!panel) throw new Error("Could not send the Verify button container in the verify channel.");
  }
  saveDB();
  return channel;
}

function verifyReviewChannelName(member) {
  const username = String(member?.user?.username || "user")
    .toLowerCase()
    .replace(/[^a-z0-9-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "") || "user";
  return `alt-${username}-${member.id}`.slice(0, 100);
}

async function ensureVerifyReviewChannel(guild, member, v = ensureVerifyData(guild.id)) {
  const pending = v.pendingApprovals?.[member.id] || {};
  let channel = pending.reviewChannelId
    ? (guild.channels.cache.get(pending.reviewChannelId) || await guild.channels.fetch(pending.reviewChannelId).catch(() => null))
    : null;
  if (channel?.isTextBased?.()) return channel;

  const roles = await ensureVerifyRoles(guild, v);
  const channels = await ensureVerifyChannels(guild, v, roles);
  const botMember = guild.members.me || await guild.members.fetchMe();
  const overwrites = [
    { id: guild.roles.everyone.id, deny: [PermissionsBitField.Flags.ViewChannel] },
    { id: member.id, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages, PermissionsBitField.Flags.ReadMessageHistory, PermissionsBitField.Flags.AttachFiles] },
    { id: botMember.id, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages, PermissionsBitField.Flags.ReadMessageHistory, PermissionsBitField.Flags.ManageChannels, PermissionsBitField.Flags.EmbedLinks] },
  ];
  const accessIds = new Set([...v.approverRoles, ...v.approverUsers]);
  for (const role of guild.roles.cache.values()) {
    if (role.id !== guild.roles.everyone.id && role.permissions.has(PermissionsBitField.Flags.ManageGuild)) accessIds.add(role.id);
  }
  const baseOverwriteIds = new Set([guild.roles.everyone.id, member.id, botMember.id]);
  for (const id of accessIds) {
    if (baseOverwriteIds.has(id)) continue;
    overwrites.push({ id, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages, PermissionsBitField.Flags.ReadMessageHistory] });
  }
  channel = await guild.channels.create({
    name: verifyReviewChannelName(member),
    type: ChannelType.GuildText,
    parent: channels.category.id,
    topic: `Verification review for ${member.user.username} (${member.id})`,
    permissionOverwrites: overwrites,
    reason: "New account verification review",
  });
  v.createdChannelIds.push(channel.id);
  v.createdChannelIds = [...new Set(v.createdChannelIds)];
  return channel;
}

async function closeVerifyReviewChannel(guild, pending, reason = "Verification review closed") {
  const channelId = pending?.reviewChannelId;
  if (!channelId) return false;
  const channel = guild.channels.cache.get(channelId) || await guild.channels.fetch(channelId).catch(() => null);
  if (!channel) return false;
  await channel.delete(reason).catch(() => {});
  return true;
}

async function syncVerifyPermissions(guild, v = ensureVerifyData(guild.id)) {
  const unverifiedRole = v.unverifiedRole ? guild.roles.cache.get(v.unverifiedRole) : null;
  const channels = [...guild.channels.cache.values()].filter(channel => channel.permissionOverwrites && channel.id !== v.category);
  let cursor = 0;
  let updated = 0;
  let failed = 0;
  const workers = unverifiedRole ? Array.from({ length: Math.min(4, channels.length || 1) }, async () => {
    while (cursor < channels.length) {
      const channel = channels[cursor++];
      const permissions = channel.id === v.channel
        ? { ViewChannel: true, ReadMessageHistory: true, SendMessages: false, AddReactions: false }
        : { ViewChannel: false };
      const ok = await channel.permissionOverwrites.edit(unverifiedRole, permissions, { reason: "Verification gate sync" }).then(() => true).catch(() => false);
      if (ok) updated++; else failed++;
    }
  }) : [];
  await Promise.all(workers);

  const botMember = guild.members.me || await guild.members.fetchMe().catch(() => null);
  const verifiedRole = v.role ? guild.roles.cache.get(v.role) : null;
  const category = v.category ? guild.channels.cache.get(v.category) : null;
  const verifyChannel = v.channel ? guild.channels.cache.get(v.channel) : null;
  if (category?.permissionOverwrites && v.createdChannelIds.includes(category.id)) {
    await category.permissionOverwrites.edit(guild.roles.everyone, { ViewChannel: false }, { reason: "Verification category sync" }).catch(() => {});
    if (botMember) {
      await category.permissionOverwrites.edit(botMember, { ViewChannel: true, ManageChannels: true }, { reason: "Verification category sync" }).catch(() => {});
    }
    for (const role of guild.roles.cache.values()) {
      if (role.id !== guild.roles.everyone.id && role.permissions.has(PermissionsBitField.Flags.ManageGuild)) {
        await category.permissionOverwrites.edit(role, { ViewChannel: true, ManageChannels: true }, { reason: "Verification manager category access" }).catch(() => {});
      }
    }
  }
  if (verifyChannel?.permissionOverwrites) {
    await verifyChannel.permissionOverwrites.edit(guild.roles.everyone, { ViewChannel: false }, { reason: "Verification channel sync" }).catch(() => {});
    if (unverifiedRole) {
      await verifyChannel.permissionOverwrites.edit(unverifiedRole, { ViewChannel: true, ReadMessageHistory: true, SendMessages: false, AddReactions: false }, { reason: "Verification channel sync" }).catch(() => {});
    }
    if (verifiedRole) {
      await verifyChannel.permissionOverwrites.edit(verifiedRole, { ViewChannel: false }, { reason: "Verification channel sync" }).catch(() => {});
    }
    if (botMember) {
      await verifyChannel.permissionOverwrites.edit(botMember, { ViewChannel: true, SendMessages: true, ReadMessageHistory: true, EmbedLinks: true }, { reason: "Verification channel sync" }).catch(() => {});
    }
  }

  const approvalChannel = v.approvalChannel ? guild.channels.cache.get(v.approvalChannel) : null;
  if (approvalChannel?.permissionOverwrites) {
    await approvalChannel.permissionOverwrites.edit(guild.roles.everyone, { ViewChannel: false }, { reason: "Verification approval sync" }).catch(() => {});
    if (unverifiedRole) {
      await approvalChannel.permissionOverwrites.edit(unverifiedRole, { ViewChannel: false }, { reason: "Verification approval sync" }).catch(() => {});
    }
    if (botMember) {
      await approvalChannel.permissionOverwrites.edit(botMember, { ViewChannel: true, SendMessages: true, ReadMessageHistory: true, EmbedLinks: true }, { reason: "Verification approval sync" }).catch(() => {});
    }
    for (const role of guild.roles.cache.values()) {
      if (role.id !== guild.roles.everyone.id && role.permissions.has(PermissionsBitField.Flags.ManageGuild)) {
        await approvalChannel.permissionOverwrites.edit(role, { ViewChannel: true, SendMessages: true, ReadMessageHistory: true }, { reason: "Verification manager access" }).catch(() => {});
      }
    }
    for (const roleId of v.approverRoles) {
      const role = guild.roles.cache.get(roleId);
      if (role) await approvalChannel.permissionOverwrites.edit(role, { ViewChannel: true, SendMessages: true, ReadMessageHistory: true }, { reason: "Verification approver access" }).catch(() => {});
    }
    for (const userId of v.approverUsers) {
      await approvalChannel.permissionOverwrites.edit(userId, { ViewChannel: true, SendMessages: true, ReadMessageHistory: true }, { reason: "Verification approver access" }).catch(() => {});
    }
  }
  return { updated, failed };
}

async function grantVerifiedRoles(member, v = ensureVerifyData(member.guild.id), reason = "Verification complete") {
  const primaryRole = v.role ? member.guild.roles.cache.get(v.role) : null;
  if (!primaryRole) return [];
  const roleIds = [primaryRole.id, ...v.extraRoles].filter(id => member.guild.roles.cache.has(id));
  const configuredRoles = roleIds.map(id => member.guild.roles.cache.get(id)).filter(Boolean);
  if (configuredRoles.some(role => role.permissions.has(PermissionsBitField.Flags.Administrator) || role.permissions.has(PermissionsBitField.Flags.ManageGuild))) return [];
  const missingRoles = configuredRoles.filter(role => !member.roles.cache.has(role.id));
  if (missingRoles.some(role => role.managed || !role.editable)) return [];
  if (missingRoles.length) await member.roles.add(missingRoles.map(role => role.id), reason);
  if (v.unverifiedRole && member.roles.cache.has(v.unverifiedRole)) {
    await member.roles.remove(v.unverifiedRole, reason).catch(() => {});
  }
  return roleIds;
}

async function setupVerifySystem(guild, options = {}) {
  const v = ensureVerifyData(guild.id);
  const freshSetup = !v.role && !v.unverifiedRole && !v.category && !v.channel && !v.approvalChannel;
  if (freshSetup && !v.ageGateConfigured) {
    v.ageGateEnabled = true;
    v.ageGateDays = 30;
  }
  const botMember = guild.members.me || await guild.members.fetchMe();
  const requiredPermissions = [
    [PermissionsBitField.Flags.ManageRoles, "Manage Roles"],
    [PermissionsBitField.Flags.ManageChannels, "Manage Channels"],
    [PermissionsBitField.Flags.ViewChannel, "View Channels"],
    [PermissionsBitField.Flags.SendMessages, "Send Messages"],
  ];
  const missingPermissions = requiredPermissions.filter(([permission]) => !botMember.permissions.has(permission)).map(([, label]) => label);
  if (missingPermissions.length) {
    throw new Error(`Bot permissions missing: ${missingPermissions.join(", ")}.`);
  }
  const roles = await ensureVerifyRoles(guild, v);
  const channels = await ensureVerifyChannels(guild, v, roles);
  await syncVerifyPermissions(guild, v);
  const panel = await sendVerifyPanel(guild, channels.verifyChannel, v);
  if (!panel) {
    throw new Error("Could not send the verification panel. Check View Channel and Send Messages permissions in the verify channel.");
  }
  v.enabled = options.enable !== false;
  saveDB();
  return { v, roles, channels, created: [...roles.created, ...channels.created] };
}

async function disableVerifySystem(guild) {
  const v = ensureVerifyData(guild.id);
  v.enabled = false;
  const unverifiedRole = v.unverifiedRole ? guild.roles.cache.get(v.unverifiedRole) : null;
  if (unverifiedRole) {
    const members = [...guild.members.cache.values()].filter(member => member.roles.cache.has(unverifiedRole.id));
    let cursor = 0;
    const workers = Array.from({ length: Math.min(3, members.length || 1) }, async () => {
      while (cursor < members.length) {
        const member = members[cursor++];
        await member.roles.remove(unverifiedRole, "Verification system disabled").catch(() => {});
      }
    });
    await Promise.all(workers);
    for (const channel of guild.channels.cache.values()) {
      await channel.permissionOverwrites?.delete?.(unverifiedRole.id, "Verification system disabled").catch(() => {});
    }
  }
  saveDB();
  return v;
}

Object.assign(globalThis, { ensureVerifyData, verifyAgeGateRuleText, verifyAgeGateStatusText, setVerifyAgeGate, isVerifyWhitelisted, canApproveVerification, canManageVerification, ensureVerifyRoles, ensureVerifyChannels, setVerifyCategory, setVerifyChannel, setVerifyApprovalChannel, ensureVerifyReviewChannel, closeVerifyReviewChannel, syncVerifyPermissions, grantVerifiedRoles, setupVerifySystem, disableVerifySystem });

function buildVerifyConfigContainer(guild, guildId, v, requesterId = null) {
  v = ensureVerifyData(guildId);
  const pend = Object.keys(v.pendingApprovals || {}).length;
  const enabled = Boolean(v.enabled);
  const tick = EMOJIS.tick;
  const cross = EMOJIS.scross;
  const configuredRole = Boolean(v.role && v.unverifiedRole);
  const configuredApproval = Boolean(v.approvalChannel);
  const configuredLogs = Boolean(v.logs);
  const configuredPanel = Boolean(v.channel && v.panelMessageId);

  const verifyConfigDropdown = new StringSelectMenuBuilder()
    .setCustomId(`vcfg_select_${guildId}_${requesterId || guild?.ownerId || "admin"}`)
    .setPlaceholder("Configure verification settings...")
    .addOptions([
      { label: v.enabled ? "Disable Verification" : "Enable Verification", value: "toggle", description: v.enabled ? "Stop gating new members" : "Enable after a confirmation warning" },
      { label: "Auto-Setup / Repair", value: "setup", description: "Create or repair roles, channels and panel" },
      { label: "Change Category", value: "setcategory", description: "Choose or replace the verification category" },
      { label: "Change Verify Channel", value: "setchannel", description: "Choose a channel and post the Verify button" },
      { label: "Set Approval Channel", value: "setapproval", description: "Channel for manual review requests" },
      { label: "Set Log Channel", value: "setlogs", description: "Channel for verification logs" },
      { label: "Set Verified Role", value: "setrole", description: "Primary role granted after verification" },
      { label: "Set Unverified Role", value: "setunverified", description: "Role assigned while awaiting verification" },
      { label: "Add Extra Verified Role", value: "addrole", description: "Grant another role after verification" },
      { label: "Remove Extra Verified Role", value: "removerole", description: "Stop granting an extra role" },
      { label: "Add Approver Role", value: "approverrole", description: "Role allowed to approve users" },
      { label: "Remove Approver Role", value: "removeapproverrole", description: "Remove role approval access" },
      { label: "Add Approver User", value: "approveruser", description: "User allowed to approve users" },
      { label: "Remove Approver User", value: "removeapproveruser", description: "Remove user approval access" },
      { label: "Age Gate / Approval", value: "agegate", description: "Set days: newer accounts need approval" },
      { label: "Set Panel Title", value: "settitle", description: "Change the verification panel title" },
      { label: "Set Panel Text", value: "setmessage", description: "Change the verification panel message" },
      { label: "Resend Verify Panel", value: "refreshpanel", description: "Replace the current verify panel" },
    ]);

  return new ContainerBuilder()
    .addTextDisplayComponents(t => t.setContent(`## ${EMOJIS.thinking} **Verification Configuration**`))
    .addSeparatorComponents(s => s.setDivider(true))
    .addTextDisplayComponents(t => t.setContent(
      `> **Status ->** \`${enabled ? "Enabled" : "Disabled"}\`\n` +
      `> **Category ->** ${v.category ? `<#${v.category}>` : "`Not configured`"}\n` +
      `> **Pending Reviews ->** \`${pend}\``
    ))
    .addSeparatorComponents(s => s.setDivider(true))
    .addTextDisplayComponents(t => t.setContent(enabled ? "***__Verification Features Enabled__***" : "***__Verification Features Information__***"))
    .addSeparatorComponents(s => s.setDivider(true))
    .addTextDisplayComponents(t => t.setContent([
      `> ${v.channel ? tick : cross} Verify Channel${v.channel ? ` - <#${v.channel}>` : ""}`,
      `> ${configuredPanel ? tick : cross} Verification Panel${configuredPanel ? "" : " - not posted"}`,
      `> ${configuredRole ? tick : cross} Verified and Unverified Roles`,
      `> ${configuredApproval ? tick : cross} Manual Approval${configuredApproval ? ` - <#${v.approvalChannel}>` : ""}`,
      `> ${v.ageGateEnabled ? tick : cross} Account Age Gate${v.ageGateEnabled ? ` - ${v.ageGateDays || 0} days` : ""}`,
      `> ${configuredLogs ? tick : cross} Verification Logs${configuredLogs ? ` - <#${v.logs}>` : ""}`,
      `> ${tick} Extra Verified Roles - \`${v.extraRoles.length}\``,
      `> ${tick} Additional Approvers - \`${v.approverUsers.length} users / ${v.approverRoles.length} roles\``,
    ].join("\n")))
    .addSeparatorComponents(s => s.setDivider(true))
    .addActionRowComponents(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId(`vcfg_enable_${guildId}`).setLabel("Enable").setEmoji(EMOJIS.tick).setStyle(ButtonStyle.Secondary).setDisabled(enabled),
      new ButtonBuilder().setCustomId(`vcfg_disable_${guildId}`).setLabel("Disable").setEmoji(EMOJIS.scross).setStyle(ButtonStyle.Secondary).setDisabled(!enabled),
      new ButtonBuilder().setCustomId(`vcfg_refreshpanel_${guildId}`).setLabel("Refresh Panel").setStyle(ButtonStyle.Secondary).setDisabled(!v.channel),
    ))
    .addActionRowComponents(new ActionRowBuilder().addComponents(verifyConfigDropdown));
}

function isPurgeMediaUrl(url = "") {
  return /\.(?:jpe?g|png|gif|webp|avif|mp4|webm|mov|m4v)(?:[?#]|$)/i.test(String(url || ""));
}

function isPurgeGifProviderUrl(url = "") {
  return /(?:tenor\.com|media\.tenor\.com|c\.tenor\.com|giphy\.com|media\d*\.giphy\.com)/i.test(String(url || ""));
}

function extractPurgeMediaUrls(content = "") {
  const urls = String(content || "").match(/https?:\/\/[^\s<>"]+/gi) || [];
  return urls
    .map(url => url.replace(/[),.;!?]+$/, ""))
    .filter(url => isPurgeMediaUrl(url) || isPurgeGifProviderUrl(url));
}

function messageHasPurgeMedia(message) {
  if (message.attachments?.size > 0) return true;
  if (extractPurgeMediaUrls(message.content).length) return true;
  return !!message.embeds?.some(embed =>
    [embed.url, embed.image?.url, embed.thumbnail?.url, embed.video?.url]
      .filter(Boolean)
      .some(url => isPurgeMediaUrl(url) || isPurgeGifProviderUrl(url))
  );
}

function safePurgeLogFileName(name = "", fallback = "purged-media") {
  const clean = String(name || fallback).replace(/[^\w.\-]/g, "_").slice(0, 96);
  return clean || fallback;
}

function purgeAttachmentLooksMedia(att) {
  const url = String(att.url || att.proxyURL || "");
  const type = String(att.contentType || "");
  return type.startsWith("image/") || type.startsWith("video/") || isPurgeMediaUrl(url);
}

async function fetchPurgeMediaBuffer(url) {
  if (typeof downloadFile === "function") return await downloadFile(url);
  const res = await fetch(url);
  return Buffer.from(await res.arrayBuffer());
}

async function sendPurgeMediaLogFiles(logCh, message, reason, guildId) {
  if (!logCh || !message || message.author?.bot) return;

  const maxBytes = 24 * 1024 * 1024;
  const items = [];
  const seen = new Set();
  const pushItem = (item) => {
    if (!item?.url || seen.has(item.url)) return;
    seen.add(item.url);
    items.push(item);
  };

  for (const [, att] of (message.attachments || [])) {
    if (!purgeAttachmentLooksMedia(att)) continue;
    pushItem({
      url: att.url || att.proxyURL,
      name: att.name || `purged-media-${message.id}`,
      size: Number(att.size || 0),
      contentType: att.contentType || "",
      direct: true,
      source: "attachment",
    });
  }

  for (const url of extractPurgeMediaUrls(message.content)) {
    pushItem({
      url,
      name: url.split("/").pop()?.split("?")[0] || `purged-media-${message.id}`,
      size: 0,
      contentType: "",
      direct: isPurgeMediaUrl(url),
      source: isPurgeGifProviderUrl(url) ? "gif link" : "link",
    });
  }

  for (const embed of (message.embeds || [])) {
    const urls = [embed.url, embed.image?.url, embed.thumbnail?.url, embed.video?.url].filter(Boolean);
    for (const url of urls) {
      if (!isPurgeMediaUrl(url) && !isPurgeGifProviderUrl(url)) continue;
      pushItem({
        url,
        name: embed.title || url.split("/").pop()?.split("?")[0] || `purged-embed-${message.id}`,
        size: 0,
        contentType: "",
        direct: isPurgeMediaUrl(url),
        source: isPurgeGifProviderUrl(url) ? "gif embed" : "embed",
      });
    }
  }

  for (const item of items) {
    const author = message.author?.tag || message.author?.username || "Unknown";
    const channel = message.channel ? `${message.channel}` : "Unknown channel";
    const safeName = safePurgeLogFileName(item.name, `purged-media-${message.id}`);
    const desc =
      `**Author:** ${author} (${message.author?.id || "unknown"})\n` +
      `**Channel:** ${channel}\n` +
      `**Reason:** ${reason}\n` +
      `**Source:** ${item.source}\n` +
      (message.content ? `**Message:** ${message.content.replace(/`/g, "'").slice(0, 500)}\n` : "") +
      `**Original:** ${item.url}`;

    if (!item.direct) {
      await sendLoggingContainer(logCh, "purgedMedia", {
        guild: logCh.guild,
        title: "Purged Media Link",
        fields: [
          { name: "Author", value: `${author} (\`${message.author?.id || "unknown"}\`)` },
          { name: "Channel", value: channel },
          { name: "Source", value: item.source },
          { name: "Original", value: item.url },
          { name: "Reason", value: reason },
        ],
      }).catch(() => {});
      continue;
    }

    if (item.size && item.size > maxBytes) {
      await sendLoggingContainer(logCh, "purgedMedia", {
        guild: logCh.guild,
        title: "Purged Media Skipped",
        fields: [
          { name: "Author", value: `${author} (\`${message.author?.id || "unknown"}\`)` },
          { name: "Channel", value: channel },
          { name: "Source", value: item.source },
          { name: "Original", value: item.url },
          { name: "Reason", value: `${reason}; file is too large to re-upload.` },
        ],
      }).catch(() => {});
      continue;
    }

    try {
      const buffer = await fetchPurgeMediaBuffer(item.url);
      if (!buffer?.length || buffer.length > maxBytes) throw new Error("file too large or empty");
      const file = new AttachmentBuilder(buffer, { name: safeName });
      const isImage = /^image\//i.test(item.contentType) ||
        /\.(?:jpe?g|png|gif|webp|avif)(?:[?#]|$)/i.test(item.url);
      await sendLoggingContainer(logCh, "purgedMedia", {
        guild: logCh.guild,
        title: "Purged Media",
        fields: [
          { name: "Author", value: `${author} (\`${message.author?.id || "unknown"}\`)` },
          { name: "Channel", value: channel },
          { name: "Source", value: item.source },
          { name: "Original", value: item.url },
          { name: "Reason", value: reason },
        ],
        media: isImage ? [`attachment://${safeName}`] : [],
        files: [file],
      }).catch(() => {});
    } catch {
      await sendLoggingContainer(logCh, "purgedMedia", {
        guild: logCh.guild,
        title: "Purged Media",
        fields: [
          { name: "Author", value: `${author} (\`${message.author?.id || "unknown"}\`)` },
          { name: "Channel", value: channel },
          { name: "Source", value: item.source },
          { name: "Original", value: item.url },
          { name: "Reason", value: `${reason}; direct upload failed.` },
        ],
      }).catch(() => {});
    }
  }
}

async function sendPurgeLog(guild, deletedMsgs, reason, moderator, sourceChannel) {
  const gId = guild.id;
  const logChId = guildData(gId).purgeLog?.channel;
  if (!logChId) return;

  const logCh = guild.channels.cache.get(logChId);
  if (!logCh) return;

  const msgs = Array.isArray(deletedMsgs) ? deletedMsgs : [deletedMsgs];
  if (msgs.length === 0) return;

  const sorted = msgs.slice().sort((a, b) => a.createdTimestamp - b.createdTimestamp);
  const count = sorted.length;
  const modStr = moderator
    ? (moderator.tag || moderator.username || moderator.user?.tag || moderator.user?.username || "Unknown Mod")
    : "Automod";
  const deletedAt = Math.floor(Date.now() / 1000);

  try {
    await sendLoggingContainer(logCh, "purge", {
      guild,
      title: "Purge Log",
      actor: moderator,
      fields: [
        { name: "Channel", value: String(sourceChannel || "Unknown") },
        { name: "Reason", value: reason },
        { name: "Deleted By", value: `${modStr}${moderator?.id ? ` (\`${moderator.id}\`)` : ""}` },
        { name: "Count", value: `${count} message${count !== 1 ? "s" : ""}` },
        { name: "Deleted Time", value: `<t:${deletedAt}:F>` },
      ],
    }).catch(() => {});

    for (const m of sorted) {
      await sendPurgeMediaLogFiles(logCh, m, reason, gId);
    }

    const lines = sorted.filter(m => !m.author?.bot).map(m => {
      const ts = `<t:${Math.floor(m.createdTimestamp / 1000)}:T>`;
      const chName = m.channel ? `#${m.channel.name || m.channel.id}` : String(sourceChannel || "Unknown channel");
      const attach = m.attachments?.size > 0
        ? ` [media: ${[...m.attachments.values()].map(a => a.name || a.url).join(", ")}]`
        : "";
      const embeds = m.embeds?.length > 0 ? " [embed]" : "";
      const stickers = m.stickers?.size > 0
        ? ` [sticker: ${[...m.stickers.values()].map(s => s.name || s.id).join(", ")}]`
        : "";
      const raw = m.content || "";
      const customEmoji = raw.match(/<a?:[A-Za-z0-9_~]+:\d+>/g);
      const emojiInfo = customEmoji?.length ? ` [emoji: ${customEmoji.join(" ")}]` : "";
      const mediaUrls = extractPurgeMediaUrls(raw);
      const gifInfo = mediaUrls.some(url => /\.gif(?:[?#]|$)/i.test(url) || isPurgeGifProviderUrl(url)) ? " [GIF]" : "";
      if (!raw.trim() && !attach && !embeds && !stickers && !emojiInfo && !gifInfo) return null;
      const content = raw
        ? raw.replace(/`/g, "'").slice(0, 200) + (raw.length > 200 ? "..." : "")
        : "[media/embed only]";
      return `${ts} ${chName} **${m.author?.tag || m.author?.username || "Unknown"}:** ${content}${attach}${embeds}${stickers}${emojiInfo}${gifInfo}`;
    }).filter(Boolean);

    let chunk = "";
    for (const line of lines) {
      const next = chunk ? chunk + "\n" + line : line;
      if (next.length > 3900) {
        await sendLoggingContainer(logCh, "purge", {
          guild,
          title: "Purged Messages",
          fields: [{ name: "Messages", value: chunk }],
        }).catch(() => {});
        chunk = line;
      } else {
        chunk = next;
      }
    }
    if (chunk) await sendLoggingContainer(logCh, "purge", {
      guild,
      title: "Purged Messages",
      fields: [{ name: "Messages", value: chunk }],
    }).catch(() => {});
  } catch (err) {
    console.error("[sendPurgeLog]", err.message);
  }
}

function normalizeSystemLookup(value = "") {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]/g, "");
}

function moderationConfirmEmoji(action, title = "") {
  const key = String(action || title || "").toLowerCase();
  if (key.includes("ban")) return EMOJIS.ban || getEmoji("ban");
  if (key.includes("kick")) return EMOJIS.kick || getEmoji("kick");
  if (key.includes("purge") || key.includes("clear")) return EMOJIS.purge || getEmoji("purge");
  if (key.includes("mute") || key.includes("timeout")) return EMOJIS.mute || getEmoji("mute");
  return EMOJIS.warn || STATUS?.warning || getEmoji("warn");
}

const moderationConfirmations = globalThis.__soezyModerationConfirmations || (globalThis.__soezyModerationConfirmations = new Map());

function buildModerationConfirmContainer({ title = "Confirm Action", action = null, target = "Unknown", reason = "No reason", moderator = "Unknown", channel = null, disabled = false, confirmationId = null }) {
  const token = String(confirmationId || Date.now());
  const confirmId = `modconfirm_confirm_${token}`;
  const cancelId = `modconfirm_cancel_${token}`;
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder()
      .setCustomId(confirmId)
      .setLabel("Confirm")
      .setStyle(ButtonStyle.Success)
      .setDisabled(disabled),
    new ButtonBuilder()
      .setCustomId(cancelId)
      .setLabel("Cancel")
      .setStyle(ButtonStyle.Danger)
      .setDisabled(disabled)
  );
  if (action === "purge" || action === "ban") {
    const inline = value => `\`${String(value || "Unknown").replace(/[`\r\n]/g, " ")}\``;
    const details = [
      `Channel ${inline(channel?.name)}`,
      `Moderator ${inline(moderator?.username || moderator?.user?.username || moderator)}`,
    ];
    if (action === "ban") details.push(`User: ${target}`, `Reason: ${reason}`);
    const container = new ContainerBuilder()
      .addTextDisplayComponents(t => t.setContent(`### ${EMOJIS.ok} ${title}`))
      .addSeparatorComponents(s => s.setSpacing(SeparatorSpacingSize.Small).setDivider(true))
      .addTextDisplayComponents(t => t.setContent(details.join("\n")))
      .addSeparatorComponents(s => s.setSpacing(SeparatorSpacingSize.Small).setDivider(true))
      .addActionRowComponents(row);
    return { container, confirmId, cancelId };
  }
  const container = new ContainerBuilder()
    .addTextDisplayComponents(t => t.setContent(`## ⚠ ${title}`))
    .addSeparatorComponents(s => s.setSpacing(SeparatorSpacingSize.Small).setDivider(true))
    .addTextDisplayComponents(t => t.setContent(
      `**User:** ${target}\n` +
      `**Reason:** ${reason}\n` +
      `**Moderator:** ${moderator}`
    ))
    .addSeparatorComponents(s => s.setSpacing(SeparatorSpacingSize.Small).setDivider(true))
    .addActionRowComponents(row);
  return { container, confirmId, cancelId };
}

async function requestModerationConfirmation(msg, options = {}) {
  if (moderationConfirmations.size >= 400) {
    await msg.reply({ components: [createErrorContainer("Busy", "Too many moderation confirmations are pending. Try again shortly.")], flags: MessageFlags.IsComponentsV2 }).catch(() => {});
    return false;
  }
  const confirmationId = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const built = buildModerationConfirmContainer({
    ...options,
    channel: msg.channel,
    title: options.title || "Confirm Action",
    target: options.target || "Unknown",
    reason: options.reason || "No reason",
    moderator: options.moderator || msg.author,
    confirmationId,
  });
  const panel = await msg.reply({ components: [built.container], flags: MessageFlags.IsComponentsV2 }).catch(() => null);
  if (!panel) return false;
  if (moderationConfirmations.size >= 400) { await panel.delete().catch(() => {}); return false; }
  return new Promise(resolve => {
    const state = {
      confirmationId, confirmId: built.confirmId, cancelId: built.cancelId, panel, msg,
      ownerId: String(msg.author.id), guildId: String(msg.guild?.id || ""), options,
      status: "pending", resolve, expiresAt: Date.now() + 300000, timer: null,
    };
    const expire = async () => {
      if (state.status !== "pending") return;
      state.status = "expired";
      moderationConfirmations.delete(state.confirmId); moderationConfirmations.delete(state.cancelId);
      const expired = buildModerationConfirmContainer({ ...options, channel: msg.channel, title: "Action Expired", target: options.target || "Unknown", reason: options.reason || "No reason", moderator: options.moderator || msg.author, disabled: true, confirmationId });
      resolve(false);
      await panel.edit({ components: [expired.container], flags: MessageFlags.IsComponentsV2 }).catch(() => {});
    };
    state.timer = setTimeout(expire, 300000);
    state.timer.unref?.();
    moderationConfirmations.set(state.confirmId, state);
    moderationConfirmations.set(state.cancelId, state);
  });
}

async function handleModerationConfirmationInteraction(interaction) {
  if (!interaction?.isButton?.() || !/^(?:modconfirm|slashmod)_/.test(String(interaction.customId || ""))) return false;
  const state = moderationConfirmations.get(interaction.customId);
  if (!state || state.status !== "pending" || state.expiresAt <= Date.now()) {
    if (state?.timer) clearTimeout(state.timer);
    if (state) { moderationConfirmations.delete(state.confirmId); moderationConfirmations.delete(state.cancelId); state.resolve(false); }
    await interaction.reply({ components: [createErrorContainer("Confirmation Expired", "This moderation confirmation is no longer active. Run the command again.")], flags: MessageFlags.IsComponentsV2 | 64 }).catch(() => {});
    return true;
  }
  if (!interaction.guild || String(interaction.guildId || "") !== state.guildId || String(interaction.user?.id || "") !== state.ownerId || interaction.message?.id !== state.panel.id) {
    await interaction.reply({ components: [createErrorContainer("Not Your Panel", "Only the command executor in the original server can use these controls.")], flags: MessageFlags.IsComponentsV2 | 64 }).catch(() => {});
    return true;
  }
  if (!interaction.member || interaction.user?.bot) {
    await interaction.reply({ components: [createErrorContainer("Confirmation Unavailable", "Your current server membership could not be verified.")], flags: MessageFlags.IsComponentsV2 | 64 }).catch(() => {});
    return true;
  }
  state.status = interaction.customId === state.confirmId ? "confirmed" : "cancelled";
  clearTimeout(state.timer);
  moderationConfirmations.delete(state.confirmId); moderationConfirmations.delete(state.cancelId);
  if (state.status === "cancelled") {
    const done = buildModerationConfirmContainer({ ...state.options, channel: state.msg.channel, title: "Action Cancelled", target: state.options.target || "Unknown", reason: state.options.reason || "No reason", moderator: state.options.moderator || state.msg.author, disabled: true, confirmationId: state.confirmationId });
    await interaction.update({ components: [done.container], flags: MessageFlags.IsComponentsV2 }).catch(() => {});
    state.resolve(false);
    return true;
  }
  try {
    await interaction.deferUpdate();
    const member = await interaction.guild.members.fetch({ user: state.ownerId, force: true });
    const permission = state.options.permission;
    const channel = state.options.channelId ? await interaction.guild.channels.fetch(state.options.channelId) : interaction.channel;
    const permissions = state.options.channelId ? channel?.permissionsFor(member) : member.permissions;
    const botMember = await interaction.guild.members.fetchMe({ force: true });
    const botPermissions = state.options.channelId ? channel?.permissionsFor(botMember) : botMember.permissions;
    if (!permission || !permissions?.has(PermissionsBitField.Flags[permission]) || !botPermissions?.has(PermissionsBitField.Flags[permission])) throw new Error("The required moderation permission is no longer available.");
    if (state.options.targetId) {
      const target = await interaction.guild.members.fetch({ user: state.options.targetId, force: true }).catch(error => {
        if (error.code === 10007 && permission === "BanMembers") return null;
        throw error;
      });
      if (target && (target.id === interaction.guild.ownerId || (member.id !== interaction.guild.ownerId && target.roles.highest.comparePositionTo(member.roles.highest) >= 0) || target.roles.highest.comparePositionTo(botMember.roles.highest) >= 0)) throw new Error("The target's role is now too high for this action.");
    }
    state.resolve({ interaction, message: state.panel });
    await state.panel.delete().catch(() => {});
  } catch (error) {
    state.resolve(false);
    const payload = { components: [createErrorContainer("Confirmation Failed", error.message || "Please run the command again.")], flags: MessageFlags.IsComponentsV2 | 64 };
    if (interaction.deferred || interaction.replied) await interaction.followUp(payload).catch(() => {});
    else await interaction.reply(payload).catch(() => {});
  }
  return true;
}

globalThis.handleModerationConfirmationInteraction = handleModerationConfirmationInteraction;

function resolveSystemName(input = "") {
  const raw = String(input || "").trim();
  const systems = typeof ALL_SYSTEMS !== "undefined" ? ALL_SYSTEMS : globalThis.ALL_SYSTEMS;
  if (!raw || !Array.isArray(systems)) return null;
  const lookup = normalizeSystemLookup(raw);
  const aliases = new Map([
    ["antibot", "antibot"],
    ["antilink", "antilink"],
    ["antinuke", "antinuke"],
    ["automod", "automod"],
    ["autorole", "autoresponder"],
    ["autorespond", "autoresponder"],
    ["autoresponder", "autoresponder"],
    ["autoreact", "autoreact"],
    ["joinDm", "joindm"],
    ["joindm", "joindm"],
    ["tempvoice", "tempvoice"],
    ["temporaryvoice", "tempvoice"],
    ["invite", "invites"],
    ["invites", "invites"],
    ["invitetracking", "invites"],
    ["ticket", "ticket"],
    ["tickets", "ticket"],
    ["giveaways", "giveaway"],
    ["giveaway", "giveaway"],
    ["mediachannels", "media"],
    ["media", "media"],
    ["sticky", "sticky"],
    ["stickymessages", "sticky"],
  ]);
  if (aliases.has(lookup)) return aliases.get(lookup);
  const matched = systems.find(sys =>
    normalizeSystemLookup(sys.name) === lookup ||
    normalizeSystemLookup(sys.displayName) === lookup ||
    (sys.linked || []).some(child => normalizeSystemLookup(child) === lookup)
  );
  return matched?.name || null;
}

