      const gifUrl = getRandomGif("lick");
      const embed = new EmbedBuilder()
        .setDescription(`<a:syum:1559656150377693305> ${msg.author} licks ${target}!`)
        .setImage(gifUrl)
        .setColor(getThemeColor(guildId))
        .setTimestamp();

